definition.script:
node {
    stage('Use string credential') {
        withCredentials([
            string(credentialsId: '{{DISCO-STRING-CREDENTIAL-ID}}', variable: 'DISCO_STRING_SECRET')
        ]) {
            sh '''#!/bin/bash
            set -euo pipefail
            test -n "$DISCO_STRING_SECRET"
            echo "DisCo string credential binding succeeded"
            '''
        }
    }
}
